T=[]
def t(title,body):T.append(dict(title=title,body=body))
t('Unit 1 · מדריך למורה','<p>כיתה ז׳ · The Same Way</p><p>סיפור, אוצר מילים, דקדוק, קריאה שימושית וכתיבה.</p><p class="created">נוצר: יום שני, י׳ בתשרי תשפ״ז (21.9.2026)</p><p class="mini">השתמשו בחצים, בסווייפ או בתפריט השקפים. מדריך זה אינו מצגת התלמידים.</p>')
t('מפת היחידה','<ol><li>מילים נחוצות והסיפור The Same Way.</li><li>דקדוק Part A במפגש כפול; אוספים וסורקים את הדף.</li><li>Part B במפגש נפרד, בהתאמה לממצאים.</li><li>סדנת קריאה עם דף דו־צדדי וחזרה בבית.</li><li>הכנה למבחן והערכה.</li></ol><p class="mini">סדר מוצע, לא מכסת שעות רשמית. מעריכים מחדש לפי העבודה בכיתה.</p>')
t('מטרות שאפשר לראות בעבודה','<ul><li>לזהות למי הודעה מיועדת, מתי ואיפה לפעול.</li><li>להבחין בין נושא מרכזי לפרט ולהביא ראיה.</li><li>לזהות סיבה ואת המידע שכינוי גוף מחליף.</li><li>לכתוב הודעה קצרה ולהבחין בין יש במקום לשייכות.</li></ul>')
t('תמיכה בלי למסור תשובה','<p>הוראות בעברית ופירושי מילים זמינים. מקריאים הוראה ומסבירים מילים לפי הצורך; במשימה עצמאית לא מסמנים אפשרות נכונה.</p><p>בשאלות הבנה מקבלים תשובה קצרה ואף עברית כשאין דרישה אחרת. מפרידים בין קושי בדקדוק, קושי בקריאה וקושי באיות.</p>')
t('שני סוגי דפים, שתי דרכי עבודה','<p><b>דפי הדקדוק:</b> השאלות במשימות 2–4 מופיעות רק בשקפים. משאירים תשובות מוקדמות; אוספים לפני הפתרונות.</p><p><b>דף סדנת הקריאה:</b> הטקסטים ומשימות 1–8 בדף. לאחר ניסיון עצמי מותר להוסיף תיקון בשורה נפרדת. משימות יציאה 9–10 נחשפות בסיום ונאספות לפני הפתרון.</p>')
t('הסיפור · רצף של 72 דקות','<p>4 דק׳ פתיחה; 5 דק׳ קריאה כללית; 7 דק׳ תמיכת מילים; 13 דק׳ פסקאות A–B ומסלול; 10 דק׳ הדאגה לגשם; 14 דק׳ המפגש בכיתה; 3 דק׳ שיחה בזוגות; 8 דק׳ עבודה בדף; 5 דק׳ בדיקה; 3 דק׳ יציאה.</p><p>עוד 8 דקות מרווח. בוחרים קריאה מלווה או משפטים לפי הצורך, בלי להעמיס שני סבבים מלאים.</p>')
t('מפתח דף הסיפור · 1–3','<p>1. הוא אוהב את שיעורי המדעים בבית הספר.</p><p>2. הליכה לתחנה ← אוטובוס ראשון ← רכבת ← אוטובוס שני ← הליכה לבית הספר.</p><p>3. False. ההפתעה בכיתה מלמדת שלא ידע שהילדים ילמדו איתו. ראיה חזקה: The boys from the journey are in my class.</p>')
t('מפתח דף הסיפור · 4–6','<p>4. הוא חושש מהגשם ומהדרך בחורף.</p><p>5. is; are.</p><p>6. יש לו חברים והוא יכול לנסוע איתם. בעיית הגשם עצמה לא נפתרה.</p><p>מקבלים ניסוחים חלופיים נכונים. דמויות הסיפור המקורי נשארות בשמותיהן.</p>')
t('הכנה למבחן · שני שיעורים','<p>שיעור ראשון: 4 דק׳ פתיחה, 10 מילות שאלה, 20 משפחת How, 6 קריאה וחזרה.</p><p>שיעור שני: 14 דק׳ חזרה על הסיפור, 12 יש ושייכות, 10 כתיבה ובדיקה, 4 יציאה. בכל שיעור 5 דקות מרווח.</p><p class="mini">How many לספירה; much לכמות או מחיר; long למשך/אורך; far למרחק; good לאיכות; small לגודל קטן; old לגיל. How big הוא ניסוח כללי לשאלת גודל.</p>')
t('Part A · מפגש כפול','<p>5 דק׳ פתיחה ומשימה 1; 14 דק׳ שייכות ומקום; 13 דק׳ יחיד ורבים ומשימה 2; 14 דק׳ שלילה; 15 דק׳ שאלות ומשימה 3; 5 דק׳ סיכום ומשימה 4; 6 דק׳ איסוף ובדיקה.</p><p>72 דקות מתוכננות + 8 דקות מרווח. אין חובה לשמוע כל זוג משפטים פעמיים.</p>')
t('Part B · מתאים את עצמו לכיתה','<p>הדף והמצגת הם בסיס זמני. אחרי סריקת A בודקים: שייכות או מקום? יחיד או רבים? סדר מילים בשאלה?</p><p>לפי הממצאים מוסיפים חזרה ממוקדת לפני was/were. שומרים מקום לקריאה ולכתיבה, ולא רק להסבר.</p>')
t('סדנת הקריאה · לפני השיעור','<p>מדפיסים <a href="files/reading-workshop.pdf">דף דו־צדדי אחד לתלמיד</a>. חלק א׳ — הודעה; חלק ב׳ — מידע. הגרפיקה מסמנת את סוג הטקסט ואינה מחליפה מידע מילולי.</p><p>התלמידים כותבים תחילה לבד. המצגת נשארת סגורה בזמן העבודה; פותחים את שקפי הבדיקה בסוף.</p>')
t('סדנת הקריאה · 80 דקות','<ul><li>0–5: פתיחה והוראות.</li><li>5–20: הודעה, משימות 1–3.</li><li>20–25: השוואת ראיות בזוגות ובדיקה קצרה בעל פה.</li><li>25–45: קטע מידע, משימות 5–8.</li><li>45–55: כתיבת הודעה — משימה 4.</li><li>55–65: מצגת משוב; 65–70: משימות 9–10 עצמאיות.</li><li>70–72: איסוף וסגירה; 8 דקות נוספות למעברים.</li></ul>')
t('שאלות שעוזרות במקום רמז לתשובה','<ul><li>איפה בטקסט מצאת את המידע?</li><li>מה השאלה מבקשת: אדם, שעה, מקום או סיבה?</li><li>האם הפרט הזה מתייחס לתיק או למטרייה?</li><li>על מי דיבר המשפט שלפני They?</li></ul><p>אם קושי משותף חוזר, עוצרים להסבר קצר בזמן העבודה.</p>')
for q in D['questions']+D['exitQuestions']:
 t('מפתח סדנה · שאלה '+q['id'],f'<p>{escape(q["q"])}</p><p><b>תשובה:</b> {escape(q["opts"][q["correct"]])}</p><p class="english evidence">{escape(q["evidence"])}</p><p>{escape(q["why"])}</p>')
t('משימה 4 · מה מקבלים?','<p>מקבלים חדר ושעה סבירים, תיאור תכולה והוראה ברורה. אין תשובה יחידה.</p><p class="english">Room 5 is open from 7:30.\nThere are chairs in the room.\nPlease put your bags under the tables.</p><p>משוב: קודם האם ההודעה מובנת, אחר כך תיקון ממוקד אחד.</p>')
t('מפתח דקדוק · Part A','<p>1: has / are.</p><p>2: is / are / has.</p><p class="english">3.1 There isn’t a book on the table.\n3.2 Is there a chair in the room?</p><p>4: has / are / Is there.</p>')
t('מפתח דקדוק · Part B','<p>1: is / has.</p><p>2: was / were.</p><p class="english">3.1 There weren’t any books in the drawer.\n3.2 Was there a ball in the drawer?</p><p>4: had / were / are.</p>')
t('מה בודקים אחרי האיסוף?','<p>משווים בין ניסיון עצמאי, תיקון והצלחה בפרט חדש. משימות 9–10 אינן מקבלות פתרון לפני האיסוף.</p><p>רושמים דפוסים: זמן ומקום, מציאת סיבה, כינוי גוף, כתיבה. תשובה חסרה אינה הוכחה לאי־הבנה; בודקים גם קצב וקריאות.</p>')
t('חזרה בבית','<p><a href="reading/?mode=home">מסלול חזרה של 10–15 דקות</a>: שני הטקסטים בחלקים, פירושים לכל מילה, שאלות עם בחירה וראיות, והודעה חדשה.</p><p>התשובה נחשפת בשקף נפרד לאחר בחירה או בקשת בדיקה. ניתן לחזור ולנסות שוב בלי חסימת ניווט.</p><p class="mini">ההקראה החדשה בהכנה; ההקראות בחומרים הקיימים פעילות.</p>')
t('המבחן הראשון וחומרי המורה','<p><a href="https://drive.google.com/file/d/1x5l2swCZE-azQmqYocBsCQ3S2WTM-2sD/view" target="_blank" rel="noopener">המבחן המוצע · PDF ב־Drive</a></p><p><a href="https://docs.google.com/document/d/1HG1acO2qYv09D7pu66zmL6zf4hoXo5Mxlrt6YOBOIkw/edit" target="_blank" rel="noopener">המבחן · גרסה לעריכה</a></p><p>עמוד סיפור ועמוד שאלות. 5 שאלות הבנה ובחירת 5 מתוך 7 משפטי כתיבה. המבחן מתמקד בהווה.</p><p class="mini">הדמיון לאורך מבחן השנה הקודמת הוא נקודת ייחוס; לא אומת שזה בדיוק המבחן הראשון דאז.</p>')
t('התאמה לתוכנית ושחזור','<p>היחידה משלבת הודעה, מידע וסיפור; הבנת פרטים ורעיון מרכזי; כתיבה קצרה. השיוך והקצב הם תכנון הוראה מקומי.</p><p><a href="https://pop.education.gov.il/tchumey_daat/english/chativat-beynayim/curriculum/basic-user-a2/">יעדי A2 — משרד החינוך</a></p><p class="mini">מקור משותף לטקסטים ולמשימות: reading/content.json. פירושי מילים נוספים הם תמיכה לשיעור ואינם טענה שנלמדה כל קבוצה 01–02.</p>')
js='''const S=TEACHER;let i=Math.max(0,Math.min(S.length-1,(parseInt(location.hash.slice(1))||1)-1));const main=document.querySelector('main');function go(n){i=Math.max(0,Math.min(S.length-1,n));main.innerHTML='<article><p class="eyebrow">Unit 1 · מדריך למורה</p><h1>'+S[i].title+'</h1>'+S[i].body+'</article>';main.scrollTop=0;document.querySelector('#count').textContent=(i+1)+' / '+S.length;document.querySelector('#back').disabled=i===0;document.querySelector('#next').disabled=i===S.length-1;document.querySelector('#jump').value=i;history.replaceState(null,'','#'+(i+1));}document.querySelector('#jump').innerHTML=S.map((s,n)=>'<option value="'+n+'">'+(n+1)+'. '+s.title+'</option>').join('');document.querySelector('#jump').onchange=e=>go(Number(e.target.value));document.querySelector('#back').onclick=()=>go(i-1);document.querySelector('#next').onclick=()=>go(i+1);document.addEventListener('keydown',e=>{if(e.target.closest('select'))return;if(['ArrowRight','ArrowDown','PageDown'].includes(e.key)){e.preventDefault();go(i+1)}if(['ArrowLeft','ArrowUp','PageUp'].includes(e.key)){e.preventDefault();go(i-1)}});let wheel=0;main.addEventListener('wheel',e=>{if(e.deltaY>0&&main.scrollTop+main.clientHeight<main.scrollHeight-3)return;if(e.deltaY<0&&main.scrollTop>3)return;e.preventDefault();if(Date.now()-wheel<500)return;wheel=Date.now();go(i+(e.deltaY>0?1:-1))},{passive:false});'''
engine=(R/'grade7/there-is-there-are/lesson.js').read_text();swipe=engine[engine.index('function installSwipe'):engine.index("installSwipe($('#stage')")];js+=swipe+"installSwipe(main,d=>go(i+d));go(i);window.teacher={go,slides:S};"
